import os
import json

# Search for task files containing '95b75add' or similar patterns
def find_task_files(base_path):
    found = []
    for root, dirs, files in os.walk(base_path):
        # Skip python site-packages and other noise
        if 'site-packages' in root or '.venv' in root:
            continue
        for fname in files:
            fpath = os.path.join(root, fname)
            try:
                with open(fpath, 'r') as f:
                    content = f.read()[:1000]  # Just peek at first 1000 chars
                    if '95b75add' in content.lower() or 'arc' in content.lower():
                        found.append((root, fname))
            except:
                pass
    return found

